export type HelpTopic={
 id:string;group:string;title:string;summary:string;figure?:FigureId;caption?:string;
 /** where to find it in the app (menu › tab › button) */
 where?:string;steps?:string[];tips?:string[];limits?:string[];related?:string[];keywords?:string;
 /** last change of the feature this topic describes (YYYY-MM-DD) */
 updated:string;
};

