/** Topic for a page / member category / member tab (page ids from App, categories from model). */
export function contextTopic(page:string,opts:{category?:string;hasProject?:boolean}={}):string{
 const c=opts.category;
 if(c){if(c==='Foundation')return 'footing';if(c==='Column')return 'column';if(c==='Beam')return 'beam';if(c==='Slab'||c==='Wall')return 'slab-wall';
  if(['Stair','Lift','Custom'].includes(c))return 'shape-model';if(c==='SteelAssembly')return 'steel';
  if(['Room','Opening','MasonryWall','Roof','Railing','Fixture'].includes(c))return 'arch';return 'civil';}
 const map:Record<string,string>={overview:'overview',wbs:'wbs',register:'register',ifc:'ifc-import',sources:'sources',boq:'boq',drawings:'drawings',packages:'packages',cutting:'cutting',engineering:'engineering',settings:'settings','general-spec':'general-spec',admin:'admin','api-manage':'api'};
 if(map[page])return map[page];if(page.startsWith('disc-'))return 'disciplines';
 return opts.hasProject?'start':'projects';
}

export const topicById=(id:string)=>helpTopics.find(t=>t.id===id);

/** Plain-text search over title, summary, steps, tips, limits and keywords; title hits rank first. */
export function searchTopics(q:string):HelpTopic[]{
 const s=q.trim().toLowerCase();if(!s)return helpTopics;
 const words=s.split(/\s+/);
 const text=(t:HelpTopic)=>[t.title,t.summary,t.where,t.keywords,...(t.steps||[]),...(t.tips||[]),...(t.limits||[])].join(' ').toLowerCase();
 return helpTopics.filter(t=>words.every(w=>text(t).includes(w))).sort((a,b)=>Number(b.title.toLowerCase().includes(s))-Number(a.title.toLowerCase().includes(s)));
}
